<?php namespace App\Domains\Payment\Models; use Illuminate\Database\Eloquent\Model; class Payment extends Model { protected $fillable = [ 'order_id', 'gateway', 'transaction_id', 'amount', 'currency', 'status', 'payload', 'processed_at', ]; protected $casts = [ 'amount' => 'decimal:2', 'payload' => 'array', 'processed_at' => 'datetime', ]; public function order() { return $this->belongsTo(\App\Domains\Order\Models\Order::class); } }